<script setup lang="ts">
import {onMounted,ref,watch} from 'vue'
import {api,message} from '../api'
import {roleNames,type Identity,type Department,type Role} from '../types'
import {session} from '../session'
import {useList} from '../useList'
import Icon from '../components/Icon.vue'
import Modal from '../components/Modal.vue'
import PageState from '../components/PageState.vue'
import Pagination from '../components/Pagination.vue'
import GovernancePanels from '../components/GovernancePanels.vue'
const {data,loading,error,load}=useList<Identity>();const page=ref(0);const departments=ref<Department[]>([]);const roles=ref<Role[]>([]);const open=ref(false);const editing=ref<Identity|null>(null);const busy=ref(false);const formError=ref('')
const permissionLabels:Record<string,string>={'spaces.read':'查看空间目录','spaces.write':'维护本院系空间','audit.read':'查询本院系审计','seats.availability.read':'查询可预约座位','seats.reservations.create':'创建本人座位预约','seats.reservations.read.own':'查看本人预约历史','seats.operations.read':'查看本院系预约运营数据'}
const form=ref({username:'',displayName:'',email:'',departmentId:'',roles:['MEMBER'],password:'',active:true})
function reload(){return load(`/users?page=${page.value}&size=20`)};watch(page,reload)
async function refreshGovernance(){try{[departments.value,roles.value]=await Promise.all([api<Department[]>('/departments'),api<Role[]>('/roles')])}catch(e){formError.value=message(e)}}
onMounted(()=>{void reload();void refreshGovernance()})
function show(user:Identity|null){editing.value=user;formError.value='';form.value=user?{username:user.username,displayName:user.displayName,email:user.email??'',departmentId:user.departmentId,roles:[...user.roles],password:'',active:user.active}:{username:'',displayName:'',email:'',departmentId:departments.value[0]?.id??'',roles:['MEMBER'],password:'',active:true};open.value=true}
async function save(){busy.value=true;formError.value='';try{if(!form.value.roles.length)throw new Error('请至少选择一个角色');const body={displayName:form.value.displayName,email:form.value.email,departmentId:form.value.departmentId,roles:form.value.roles};if(editing.value)await api(`/users/${editing.value.id}`,'PUT',{...body,active:form.value.active});else await api('/users','POST',{...body,username:form.value.username,password:form.value.password});form.value.password='';open.value=false;await reload()}catch(e){formError.value=message(e)}finally{busy.value=false}}
</script>
<template><div class="page-heading"><div><div class="eyebrow">ACCESS / PEOPLE</div><h1>账号与权限</h1><p>为每位成员分配合适的角色，让协作有边界。</p></div><button class="button" @click="show(null)"><Icon name="plus" :size="17"/>新增账号</button></div><div class="info-strip"><Icon name="shield" :size="18"/><p>管理员管理全局；空间管理员和审计员受所属院系约束。权限修改后，下次请求立即生效。</p></div><section class="panel"><div class="panel-heading"><h2>平台成员 <span class="count-pill">{{data.total}}</span></h2><button class="text-link" @click="reload"><Icon name="refresh" :size="16"/>刷新</button></div><PageState :loading="loading" :error="error" :empty="!data.items.length" @retry="reload"><div class="table-scroll"><table><thead><tr><th>成员</th><th>所属院系</th><th>角色</th><th>状态</th><th class="align-right">操作</th></tr></thead><tbody><tr v-for="user in data.items" :key="user.id"><td><div class="entity-cell"><span class="avatar table-avatar">{{user.displayName.slice(0,1)}}</span><div><strong>{{user.displayName}} <span v-if="user.id===session.user?.id" class="self-tag">你</span></strong><small>{{user.username}} · {{user.email||'未设置邮箱'}}</small></div></div></td><td>{{departments.find(d=>d.id===user.departmentId)?.name??'—'}}</td><td><div class="feature-chips"><span v-for="role in user.roles" :key="role">{{roles.find(r=>r.code===role)?.name??roleNames[role]??role}}</span></div></td><td><span class="badge" :class="{neutral:!user.active}"><i/>{{user.active?'正常':'已停用'}}</span></td><td class="align-right"><button class="text-link" @click="show(user)">编辑权限</button></td></tr></tbody></table></div><Pagination :page="page" :total="data.total" :size="20" @change="page=$event"/></PageState></section><GovernancePanels :roles="roles" :departments="departments" @updated="refreshGovernance"/><Modal v-if="open" :title="editing?'编辑账号与权限':'新增账号'" @close="open=false;form.password='' "><form class="form-body" @submit.prevent="save"><div class="form-grid"><label>账号<input v-model="form.username" required pattern="[a-zA-Z0-9._-]{3,48}" maxlength="48" :disabled="!!editing" placeholder="3–48 位字母、数字等"></label><label>显示名称<input v-model="form.displayName" required maxlength="64"></label></div><label>邮箱<input v-model.trim="form.email" type="email" required maxlength="254" autocomplete="email"><small>预约提醒邮件将发送到此地址。</small></label><label>所属院系<select v-model="form.departmentId" required :disabled="editing?.id===session.user?.id"><option v-for="dep in departments" :key="dep.id" :value="dep.id">{{dep.name}}</option></select></label><label v-if="!editing">初始密码<input v-model="form.password" type="password" autocomplete="new-password" minlength="12" maxlength="72" required><small>至少 12 个字符。请通过私下渠道告知本人。</small></label><fieldset class="role-fieldset"><legend>分配角色</legend><label v-for="role in roles" :key="role.code" class="role-option"><input v-model="form.roles" type="checkbox" :value="role.code" :disabled="editing?.id===session.user?.id"><div><strong>{{role.name}}</strong><small>{{role.code==='ADMIN'?'全局账号、资源、通知与审计管理':role.code==='SPACE_MANAGER'?'维护本院系的教室与座位':role.code==='AUDITOR'?'查阅本院系的操作审计':role.code==='MEMBER'?'查看空间目录、接收本人通知':role.permissions.map(p=>permissionLabels[p]??p).join('、')}}</small></div></label></fieldset><label v-if="editing" class="checkbox-label"><input v-model="form.active" type="checkbox" :disabled="editing.id===session.user?.id">启用账号</label><p v-if="editing?.id===session.user?.id" class="muted small-text">为保留管理入口，自己的角色、院系及启用状态须由另一位管理员修改。</p><p v-if="formError" class="form-error" role="alert">{{formError}}</p><div class="form-actions"><button type="button" class="button secondary" @click="open=false;form.password='' ">取消</button><button class="button" :disabled="busy">{{busy?'正在保存…':'保存账号'}}</button></div></form></Modal></template>
